window.AURA_MATH_EXAMS=[{"id":"de1","title":"Giữa kỳ I – Đề số 1","verified":true,"ready":true,"desc":"10 câu trắc nghiệm + 5 bài tự luận • ảnh gốc đã đối chiếu từ DOCX","sourceId":"1oVyfQValDi1BnRBO4haR4x3IbMIDsoOk","mc":[{"stem":"Viết tập hợp B = {x ∈ N* | x ≤ 7} bằng cách liệt kê các phần tử:","options":["B = {1;2;3;4;5;6;7}","B = {1;2;3;4;5;6}","B = {0;1;2;3;4;5;6;7}","B = {1;3;5;7}"],"answer":"A"},{"stem":"Cho tập hợp A = {1; 2; a; b}, khẳng định nào dưới đây SAI?","options":["1 ∈ A","a ∈ A","5 ∉ A","b ∉ A"],"answer":"D"},{"stem":"Cho số tự nhiên x, biết x + 20 = 55 khi đó","options":["x = 20","x = 25","x = 30","x = 35"],"answer":"D"},{"stem":"Phép tính 3⁴⁰·3²⁰⁰ : 3⁵⁰ có kết quả là:","options":["3⁵⁴","3¹⁰⁰","3⁵⁰","3¹⁹⁰"],"answer":"D"},{"stem":"Kết quả của phép tính 88 + 3 + 12 là:","options":["103","113","112","122"],"answer":"A"},{"stem":"Ba số tự nhiên liên tiếp giảm dần là:","options":["62; 61; 60","57; 55; 53","60; 61; 62","67; 56; 54"],"answer":"A"},{"stem":"Thứ tự thực hiện các phép tính trong một biểu thức không có dấu ngoặc, có các phép tính: cộng, trừ, nhân, chia và nâng lên lũy thừa là:","options":["Nhân, chia → Cộng, trừ → Lũy thừa","Lũy thừa → Cộng, trừ → Nhân, chia","Lũy thừa → Nhân, chia → Cộng, trừ","Nhân, chia → Lũy thừa → Cộng, trừ"],"answer":"C"},{"stem":"Trong hình chữ nhật","options":["Hai đường chéo bằng nhau và cắt nhau tại trung điểm của mỗi đường.","Hai đường chéo không bằng nhau.","Hai đường chéo song song với nhau.","Hai đường chéo vuông góc với nhau."],"answer":"A"},{"stem":"Tính chất nào không phải là của hình thang cân?","options":["Hai đường chéo bằng nhau.","Có các góc đối bằng nhau.","Có hai cạnh đáy song song.","Có hai cạnh bên bằng nhau."],"answer":"B"},{"stem":"Yếu tố nào sau đây không phải của hình thoi?","options":["Hai đường chéo vuông góc với nhau.","Có 4 cạnh bằng nhau.","Hai cặp cạnh đối diện song song với nhau.","Có 4 góc vuông."],"answer":"D"}],"essay":[{"prompt":"Bài 1. Thực hiện các phép tính sau:\na) 25·35 + 25·73 – 25·8\nb) 3³ – 2⁸ : 2⁵ + 6·5²\nc) 107 – {38 + [7·3² – 24 : 6 + (9 – 7)³]} : 15\nd) Tìm x, biết: 2ˣ + 2ˣ⁺¹ = 24","solution":"a) 2500\nb) 169\nc) 100\nd) x = 3"},{"prompt":"Bài 2. Mẹ Lan mang 160 000 đồng vào siêu thị mua 2 kg khoai tây và 5 kg gạo. Giá mỗi kilogram khoai tây là 24 500 đồng, mỗi kilogram gạo là 21 000 đồng. Hỏi mẹ Lan còn lại bao nhiêu tiền?","solution":"Tiền mua hàng: 2×24 500 + 5×21 000 = 154 000 đồng. Còn lại: 160 000 – 154 000 = 6 000 đồng."},{"prompt":"Bài 3. Lớp 6A thực hiện kế hoạch nhỏ, mỗi ngày 5 kg giấy vụn. Sau 2 tuần thực hiện các bạn đem bán số giấy vụn đã quyên góp được với giá mỗi kg là 15 000 đồng. Sau khi thực hiện kế hoạch nhỏ các bạn đã thu được bao nhiêu tiền? (biết 1 tuần là 7 ngày)","solution":"2 tuần = 14 ngày. Khối lượng giấy: 5×14 = 70 kg. Số tiền: 70×15 000 = 1 050 000 đồng."},{"prompt":"Bài 4. Trong một khu vườn hình chữ nhật, người ta làm một lối đi lát sỏi với các kích thước như hình vẽ sau.\na) Tính diện tích lối đi.\nb) Chi phí cho mỗi mét vuông làm lối đi hết 120 nghìn đồng. Hỏi chi phí để làm lối đi là bao nhiêu?","solution":"Lối đi là hình bình hành có đáy 2 m và chiều cao 20 m.\na) Diện tích: 2×20 = 40 m².\nb) Chi phí: 40×120 000 = 4 800 000 đồng.","image":"data:image/png;base64,"},{"prompt":"Bài 5. Quan sát hình bên.\na) Em hãy mô tả về cạnh, góc và đường chéo của hình bình hành ABCD. Nêu các cạnh song song, cạnh bằng nhau.\nb) Hình bình hành ABCD có cạnh AB = 5 cm và cạnh BC = 3 cm. Tính cạnh CD, AD.","solution":"a) AB ∥ CD, AD ∥ BC; AB = CD, AD = BC; các góc đối bằng nhau; hai đường chéo cắt nhau tại trung điểm mỗi đường.\nb) CD = 5 cm; AD = 3 cm.","image":"data:image/png;base64,"}]}];